#include <endian.h>
#include "p10_hcode_image_defines.H"
#include "p10_hcd_memmap_qme_sram.H"
#include "p10_hcd_memmap_occ_sram.H"

#include "p10_getsram.H"
#include "p10_putsram.H"
#include "p10_getputsram_utils.H"

